using System.Text.Json;
namespace StarlightSyndicateDemo;
public static class ProductionTestsE
{
 public static void Run()
 {
  SkillCatalog.VerificationAllV=false;int n=0;void Check(bool ok,string name){if(!ok)throw new Exception("STAGE E FAIL / "+name);n++;Console.WriteLine("STAGE E PASS / "+name);}
  var old=Environment.GetEnvironmentVariable("STARLIGHT_SAVE_DIR");var dir=Path.Combine(Path.GetTempPath(),"production-e-"+Guid.NewGuid().ToString("N"));Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",dir);
  try{
   var w=new DemoWorld();w.NewGame(0);w.WalletFunds=100000;var lab=w.DeployFacilityE("Laboratory")!;Check(lab!=null,"Funded laboratory deployment");Check(w.DeployFacilityE("Laboratory")==null,"Duplicate deployment rejected");Check(w.DeployFacilityE("Refinery")==null,"High-security refinery blocked");
   foreach(var i in ProductionCatalogE.Items)Check(w.BuyBlueprint(i.Id).Length>0,"Generic blueprint bypass blocked / "+i.Id);
   w.Hangar["e_polymer"]=10;w.Hangar["e_coolant"]=10;w.Hangar["ind_34"]=50;decimal balance=w.Balance;
   Check(w.InstallProductionE("component",lab!.Id)=="","Component job installation");Check(w.Hangar["e_polymer"]==0&&w.Balance==balance-25,"Atomic declared inputs and fee");var job=w.Production.Jobs.Last();Check(w.DeliverProductionE(job.Id).Length>0,"No early delivery");w.WaitDocked(.5);Check(w.DeliverProductionE(job.Id)==""&&w.Hangar["e_component"]==5,"Timed component delivery");Check(w.DeliverProductionE(job.Id).Length>0&&w.Hangar["e_component"]==5,"Delivery idempotence");Check(w.InstallProductionE("advanced",lab.Id).Length>0,"Advanced manufacture requires invented BPC");
   var bp=new OwnedBlueprint37{Item="analyzer",Original=false,Runs=3,Station=w.StationKey44};w.Industry.Blueprints.Add(bp);w.Hangar["d_datacore"]=12;w.Hangar["e_decryptor"]=1;w.Production.Random=1;
   Check(w.InventProductionE(lab.Id,bp.Id,true)==""&&bp.Runs==2&&w.Hangar["d_datacore"]==8&&w.Hangar["e_decryptor"]==0,"Invention consumes BPC run, datacores and decryptor");var invention=w.Production.Jobs.Last();bool outcome=invention.Success;w.Save();var loaded=new DemoWorld();Check(loaded.Load()&&loaded.Production.Jobs.Last().Success==outcome&&loaded.Production.Random==w.Production.Random,"Sealed invention outcome and RNG persist");w.WaitDocked(1);Check(w.DeliverProductionE(invention.Id)=="","Invention finishes on shared clock");Check(outcome&&w.Industry.Blueprints.Last().Item=="e_t2"&&w.Industry.Blueprints.Last().Runs==12,"Seeded success creates licensed advanced BPC");
   w.Hangar["analyzer"]=1;Check(w.InstallProductionE("advanced",lab.Id)=="","Invented BPC feeds advanced production");var advanced=w.Production.Jobs.Last();Check(w.Industry.Blueprints.Last().Runs==11,"Advanced manufacture consumes limited run");Check(w.CancelProductionE(advanced.Id)==""&&w.Hangar["analyzer"]==0,"Cancellation keeps consumed inputs");Check(w.CancelProductionE(advanced.Id).Length>0,"Cancellation settles once");
   var colony=w.DeployColonyE("Industrial colony")!;Check(colony!=null,"Funded colony command centre");w.WaitDocked(1);Check(colony!.Deposit==99900&&colony.Raw==50&&colony.Product==5,"Extractor link and processor material conservation");w.SimulationUtc=w.SimulationUtc.AddHours(1000);w.AdvanceProductionE();Check(colony.Raw<=colony.Capacity&&colony.Product<=colony.Capacity,"Long advance obeys both buffer limits");Check(w.UpgradeColonyE(colony.Id)==""&&colony.LinkRate==100,"Upgrade repairs link throughput");decimal product=colony.Product;Check(w.ExportColonyE(colony.Id)==""&&w.Hangar["e_coolant"]==product,"Customs export moves physical product");Check(w.ExportColonyE(colony.Id).Length>0,"Empty output cannot duplicate export");
   w.SystemId="blackquota";var refinery=w.DeployFacilityE("Refinery")!;Check(refinery!=null,"Low-security refinery deployment");w.Hangar["fuel"]=100;Check(w.SupplyFacilityE(refinery!.Id,"fuel",100)==""&&refinery.Stock["fuel"]==100,"Supply transfers real fuel");var moon=w.SurveyMoonE("Manual moon")!;Check(moon!=null&&w.ScheduleMoonE(moon.Id,refinery.Id,false)=="","Survey and manual extraction installation");Check(w.FractureMoonE(moon!.Id).Length>0,"Cannot fracture early");w.WaitDocked(24);Check(w.FractureMoonE(moon.Id)==""&&moon.Rocks==1000&&moon.Deposit==9000,"Fracture reserves finite deposit into rocks");Check(w.FractureMoonE(moon.Id).Length>0,"Chunk cannot fracture twice");Check(w.MineMoonE(moon.Id,2000)==""&&w.Hangar["e_moon"]==1000&&moon.Rocks==0,"Near-depleted mining clamps to actual rock stock");
   Check(w.ScheduleMoonE(moon.Id,refinery.Id,true)=="","Automated drill restart");decimal fuel=refinery.Stock["fuel"],deposit=moon.Deposit;w.WaitDocked(2);Check(refinery.Stock["fuel"]==fuel-2&&moon.Deposit==deposit-100&&moon.Stock["e_moon"]==40,"Drill consumes fuel and deposit at declared recovery");Check(w.RaidMoonE(moon.Id,10)==10&&moon.Stock["e_moon"]==30,"Raid changes collectible output");Check(w.CollectMoonE(moon.Id)==""&&w.Hangar["e_moon"]==1030,"Collection accounts for raided stock");Check(w.SetFacilityE(refinery.Id,false)=="","Facility services can go offline");deposit=moon.Deposit;w.WaitDocked(4);Check(moon.Deposit==deposit,"Offline drill cannot produce");Check(w.SetFacilityE(refinery.Id,true)=="","Services restored");refinery.Stock["fuel"]=0;w.WaitDocked(2);Check(moon.Deposit==deposit,"Fuel starvation blocks output");
   w.Hangar["e_formula"]=1;w.Hangar["fuel"]=5;w.Hangar["e_moon"]=40;Check(w.InstallProductionE("polymer",refinery.Id)=="","Formula and fuel enable reaction");Check(w.Hangar["e_formula"]==1&&w.Hangar["fuel"]==0,"Formula reusable while reaction fuel consumed");var reaction=w.Production.Jobs.Last();w.DestroyFacilityE(refinery.Id);Check(reaction.State=="Lost"&&moon.State=="Lost","Destruction settles production and moon operation");Check(w.DeliverProductionE(reaction.Id).Length>0,"Destroyed job cannot deliver");
   var tree=w.ProductionTreeE("e_t2",1);Check(tree.Any(s=>s.Contains("coolant",StringComparison.OrdinalIgnoreCase))&&tree.Any(s=>s.Contains("short")),"Production tree exposes nested shortages");w.Save();loaded=new();Check(loaded.Load()&&loaded.Production.Facilities.Last().Destroyed&&loaded.Production.Colonies.Single().LinkRate==100,"Facility and planetary state roundtrip");var data=JsonSerializer.Deserialize<DemoWorld.SaveData>(File.ReadAllText(DemoWorld.SavePath),WeaponCatalog.JsonOptions)!;Check(data.SaveSchemaVersion==54,"Schema 51 writer");data.SaveSchemaVersion=49;data.Production=null;string original=JsonSerializer.Serialize(data,WeaponCatalog.JsonOptions);File.WriteAllText(DemoWorld.SavePath,original);loaded=new();Check(loaded.Load()&&File.ReadAllText(DemoWorld.SavePath+".pre-stage-e.bak")==original,"Exact Stage D migration backup");
   w.SystemId="blackquota";w.Hangar["e_mutator"]=1;var repair=w.Player.Defense[1];Check(w.MutateDefenseE(1)==""&&repair.MutatedE&&!repair.Online,"Mutation consumes eligible identity and leaves it offline");var quote=w.Player.DefenseQuoteB(repair);Check(repair.MutationAmountE>=.8f&&repair.MutationAmountE<=1.2f&&quote.Amount>0,"Mutation ranges and authoritative repair quote");Check(w.MutateDefenseE(1).Length>0,"Repeated mutation rejected");w.Save();loaded=new();Check(loaded.Load()&&loaded.Player.Defense[1].MutationAmountE==repair.MutationAmountE&&loaded.Player.Defense[1].InstanceId==repair.InstanceId,"Unique mutated values survive save and reload");
   var field=w.DiscoverPhaseE()!;Check(field!=null&&w.CollectPhaseE().Length>0,"Phased field begins unbreached");w.WaitDocked(1);Check(w.CollectPhaseE()==""&&w.Hangar["e_prism"]==10&&field!.Remaining==990,"Phased-out field harvest efficiency");w.Hangar["e_component"]=5;Check(w.AnchorPhaseE()==""&&w.Hangar["e_component"]==0,"Phase anchor consumes physical components");Check(w.EnergizePhaseE().Length>0,"Ordinary hull cannot energize anchor");w.WaitDocked(3);Check(w.PhaseStatusE(field!)=="Collapsed"&&w.CollectPhaseE().Length>0,"Field collapse cannot be bypassed by collecting");Check(w.DiscoverPhaseE()==field&&field!.Remaining==990,"Rediscovery does not regenerate finite field");Check(w.BuyProductionSupplyE("e_formula")=="","Finite specialist licence acquisition");for(int i=0;i<4;i++)w.BuyProductionSupplyE("e_formula");Check(w.BuyProductionSupplyE("e_formula").Length>0,"Specialist opening stock cannot replenish invisibly");
   w.Hangar["e_component"]=0;w.Hangar["e_polymer"]=20;w.Hangar["e_t3"]=0;var allocated=w.ProductionTreeE("e_t3",1);Check(allocated.Count(s=>s.Contains("Composite polymer"))==2&&allocated.Last(s=>s.Contains("Composite polymer")).EndsWith("short 20"),"Production tree does not allocate the same local stock twice");
   var invalid=new ProductionStateE();invalid.Colonies.Add(new(){Capacity=-1});bool rejected=false;try{DemoWorld.ValidateProductionE(invalid);}catch(InvalidDataException){rejected=true;}Check(rejected,"Invalid production state rejected");Console.WriteLine(n+" Stage E checks passed.");
  }finally{Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",old);if(Directory.Exists(dir))Directory.Delete(dir,true);}
 }
}
